            let verification = Verification(
                questId: quest.id,
                questTitle: quest.title,
                sourceDailyEntryId: draft.id,
                completion: index == 2 ? .missed : .done,
                valueRating: index == 1 ? .medium : .high,
                calibrationNote: "Verification \(index)"
