                return
            }
            todayLoopMessage = "正在重试 AI 追问。"
            lastAIFailureMessage = nil
            canRetryCurrentAI = false
            Task {
                await generateQuestionsWithAIOrFallback(draftID: draftID, allowsFallback: false)
            }
        case .reviewQuests:
            guard hasAnsweredReflectionQuestion else {
