            lastAIFailureMessage = nil
            canRetryCurrentAI = false
            Task {
                await generatePrincipleWithAIOrFallback(draftID: draftID, allowsFallback: false)
            }
        default:
            todayLoopMessage = "当前步骤没有可重试的 AI 调用。"
        }
