    }

    func acceptProjectLinkCandidate(_ linkCandidate: ProjectLinkCandidate) async {
        guard let projectLinkRepository else {
            projectSuggestionMessage = "本地存储暂不可用。"
            return
        }

        guard let projectId = linkCandidate.projectId else {
